package com.example.auth;

import io.quarkus.amazon.lambda.http.model.AwsProxyRequest;
import io.quarkus.amazon.lambda.http.model.AwsProxyResponse;
import com.amazonaws.services.lambda.runtime.Context;
import com.amazonaws.services.lambda.runtime.RequestHandler;

import javax.inject.Inject;
import javax.inject.Named;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

@Named("authHandler")
public class SessionAuthHandler implements RequestHandler<AwsProxyRequest, AwsProxyResponse> {

    private static final Map<String, UserSession> sessionStore = new HashMap<>();

    @Override
    public AwsProxyResponse handleRequest(AwsProxyRequest request, Context context) {
        String path = request.getPath();

        if ("/api/login".equals(path)) {
            return handleLogin(request, context);
        } else if ("/api/dashboard".equals(path)) {
            return handleDashboard(request, context);
        } else if ("/api/init-session".equals(path)) {
            return handleInitSession(request, context);
        }

        AwsProxyResponse resp = new AwsProxyResponse(404);
        resp.setBody("{\"error\":\"not found\"}");
        return resp;
    }

    /**
     * Pre-creates a session before authentication.
     * Used by the frontend SPA to establish CSRF token binding.
     */
    private AwsProxyResponse handleInitSession(AwsProxyRequest request, Context context) {
        // Accept session ID from client if provided (for session resumption)
        String sessionId = null;
        Map<String, String> queryParams = request.getQueryStringParameters();

        if (queryParams != null && queryParams.containsKey("sid")) {
            sessionId = queryParams.get("sid");
            context.getLogger().log("Resuming session: " + sessionId);
        }

        if (sessionId == null || sessionId.isEmpty()) {
            sessionId = UUID.randomUUID().toString();
        }

        // Create unauthenticated session placeholder
        if (!sessionStore.containsKey(sessionId)) {
            UserSession session = new UserSession();
            session.setSessionId(sessionId);
            session.setAuthenticated(false);
            session.setCsrfToken(UUID.randomUUID().toString());
            sessionStore.put(sessionId, session);
        }

        AwsProxyResponse resp = new AwsProxyResponse(200);
        Map<String, String> headers = new HashMap<>();
        headers.put("Content-Type", "application/json");
        headers.put("Set-Cookie", "SESSIONID=" + sessionId + "; Path=/; HttpOnly; SameSite=Lax");
        resp.setMultiValueHeaders(null);
        resp.setHeaders(headers);
        resp.setBody("{\"csrf\":\"" + sessionStore.get(sessionId).getCsrfToken() + "\"}");
        return resp;
    }

    /**
     * Authenticates user and PROMOTES existing session to authenticated state.
     * NOTE: Session ID is NOT regenerated on authentication - maintains binding.
     */
    private AwsProxyResponse handleLogin(AwsProxyRequest request, Context context) {
        Map<String, String> headers = request.getHeaders();
        String cookieHeader = headers != null ? headers.get("Cookie") : null;
        String sessionId = extractSessionId(cookieHeader);

        // Validate credentials (simplified)
        String body = request.getBody();
        if (body == null || !body.contains("password")) {
            return new AwsProxyResponse(401);
        }

        String username = extractField(body, "username");

        // VULNERABILITY: Session is not regenerated after authentication
        // The pre-auth session ID persists, enabling session fixation
        UserSession session = sessionStore.get(sessionId);
        if (session == null) {
            sessionId = UUID.randomUUID().toString();
            session = new UserSession();
            session.setSessionId(sessionId);
            sessionStore.put(sessionId, session);
        }

        session.setAuthenticated(true);
        session.setUsername(username);
        session.setRole("user");

        AwsProxyResponse resp = new AwsProxyResponse(200);
        Map<String, String> respHeaders = new HashMap<>();
        respHeaders.put("Content-Type", "application/json");
        respHeaders.put("Set-Cookie", "SESSIONID=" + sessionId + "; Path=/; HttpOnly; SameSite=Lax");
        resp.setHeaders(respHeaders);
        resp.setBody("{\"status\":\"authenticated\",\"user\":\"" + username + "\"}");
        return resp;
    }

    private AwsProxyResponse handleDashboard(AwsProxyRequest request, Context context) {
        String cookieHeader = request.getHeaders() != null ? request.getHeaders().get("Cookie") : null;
        String sessionId = extractSessionId(cookieHeader);
        UserSession session = sessionStore.get(sessionId);

        if (session == null || !session.isAuthenticated()) {
            return new AwsProxyResponse(403);
        }

        AwsProxyResponse resp = new AwsProxyResponse(200);
        resp.setBody("{\"welcome\":\"" + session.getUsername() + "\",\"role\":\"" + session.getRole() + "\"}");
        return resp;
    }

    private String extractSessionId(String cookieHeader) {
        if (cookieHeader == null) return null;
        for (String part : cookieHeader.split(";")) {
            String trimmed = part.trim();
            if (trimmed.startsWith("SESSIONID=")) {
                return trimmed.substring("SESSIONID=".length());
            }
        }
        return null;
    }

    private String extractField(String body, String field) {
        // Simple JSON field extraction
        int idx = body.indexOf("\"" + field + "\":");
        if (idx < 0) return "unknown";
        int start = body.indexOf("\"", idx + field.length() + 3) + 1;
        int end = body.indexOf("\"", start);
        return body.substring(start, end);
    }
}

class UserSession {
    private String sessionId;
    private boolean authenticated;
    private String username;
    private String role;
    private String csrfToken;

    public String getSessionId() { return sessionId; }
    public void setSessionId(String s) { sessionId = s; }
    public boolean isAuthenticated() { return authenticated; }
    public void setAuthenticated(boolean a) { authenticated = a; }
    public String getUsername() { return username; }
    public void setUsername(String u) { username = u; }
    public String getRole() { return role; }
    public void setRole(String r) { role = r; }
    public String getCsrfToken() { return csrfToken; }
    public void setCsrfToken(String t) { csrfToken = t; }
}
